import{_ as t,c as a,o as n,a2 as r}from"./chunks/framework.BTUiiAmu.js";const g=JSON.parse('{"title":"Kubernetes Auditing","description":"Gardener extension controller which deploys an auditlog forwarder sending Kubernetes Audit Events to configured backends.","frontmatter":{"description":"Gardener extension controller which deploys an auditlog forwarder sending Kubernetes Audit Events to configured backends.","github_repo":"https://github.com/gardener/gardener-extension-auditing","github_subdir":".","params":{"github_branch":"main"},"path_base_for_github_subdir":{"from":"content/docs/extensions/others/gardener-extension-auditing/_index.md","to":"README.md"},"title":"Kubernetes Auditing","prev":false,"next":false},"headers":[],"relativePath":"docs/extensions/others/gardener-extension-auditing/index.md","filePath":"docs/extensions/others/gardener-extension-auditing/index.md","lastUpdated":null}'),o={name:"docs/extensions/others/gardener-extension-auditing/index.md"};function i(s,e,d,l,u,c){return n(),a("div",null,e[0]||(e[0]=[r('<h1 id="gardener-extension-auditing" tabindex="-1"><a href="https://gardener.cloud" target="_blank" rel="noreferrer">Gardener Extension Auditing</a> <a class="header-anchor" href="#gardener-extension-auditing" aria-label="Permalink to &quot;[Gardener Extension Auditing](https://gardener.cloud)&quot;">​</a></h1><p><a href="https://github.com/gardener/gardener-extension-auditing/actions/workflows/non-release.yaml" target="_blank" rel="noreferrer"><img src="https://github.com/gardener/gardener-extension-auditing/raw/workflows/non-release.yaml/badge.svg" alt="Build"></a><a href="https://goreportcard.com/report/github.com/gardener/gardener-extension-auditing" target="_blank" rel="noreferrer"><img src="https://goreportcard.com/badge/github.com/gardener/gardener-extension-auditing" alt="Go Report Card"></a><a href="https://api.reuse.software/info/github.com/gardener/gardener-extension-auditing" target="_blank" rel="noreferrer"><img src="https://api.reuse.software/badge/github.com/gardener/gardener-extension-auditing" alt="REUSE status"></a></p><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>Gardener extension controller which deploys an auditlog forwarder sending Audit Events to configured backends.</p><h3 id="use-case" tabindex="-1">Use Case <a class="header-anchor" href="#use-case" aria-label="Permalink to &quot;Use Case&quot;">​</a></h3><p>Kubernetes audit logs are essential for security investigations, compliance evidence, and operational troubleshooting. Long‑term storage, external analysis, SIEM ingestion, or near real‑time alerting requires that these audit events leave the cluster boundary in a reliable and secure way.</p><p>The Gardener auditing extension (type <code>auditing</code>) deploys and manages the <a href="https://github.com/gardener/auditlog-forwarder" target="_blank" rel="noreferrer">auditlog-forwarder</a> inside the control plane of a Shoot cluster. This webhook component receives the API server audit logs, enriches them with Gardener specific metadata and forwards the events to one or more remote backends.</p><h3 id="solution-overview" tabindex="-1">Solution Overview <a class="header-anchor" href="#solution-overview" aria-label="Permalink to &quot;Solution Overview&quot;">​</a></h3><ol><li>You configure an audit policy for the Shoot&#39;s kube-apiserver (via <code>spec.kubernetes.kubeAPIServer.auditConfig.auditPolicy</code>).</li><li>You enable the auditing extension on the Shoot and provide a list of forwarding backends in <code>providerConfig</code>.</li><li>The extension reconciler deploys the <code>auditlog-forwarder</code> Deployment plus supporting objects (ServiceAccount, RBAC, VPA, etc.) into the Shoot namespace in the Seed cluster.</li><li>The forwarder receives audit events from the kube-apiserver (sent over HTTPS on a webhook endpoint), enriches them with Gardener specific metadata and sends them to the configured remote endpoints.</li></ol><h3 id="data-flow" tabindex="-1">Data Flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data Flow&quot;">​</a></h3><p>kube-apiserver -&gt; auditlog-forwarder -&gt; external receiver(s)</p><h3 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Multiple backends (fan‑out) – each event is attempted to be delivered to all configured backends. (this function is currently limited to a single backend)</li><li>HTTPS delivery via mutual TLS.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Current API focuses on HTTP(S) backends. Future versions may add additional backend types (e.g. OTLP).</p></div><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><ul><li><a href="/pr-preview/pr-838/docs/extensions/others/gardener-extension-auditing/usage-configuration/">Configuring the Auditing Extension</a> - learn how to enable and configure the auditing extension for shoot clusters</li><li><a href="/pr-preview/pr-838/docs/extensions/others/gardener-extension-auditing/usage-event-format/">Audit Event Format</a> - understand the format of audit events and Gardener-specific annotations</li></ul><h2 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h2><ul><li><a href="/pr-preview/pr-838/docs/extensions/others/gardener-extension-auditing/operations-configuration/">Configuring the Auditing Extension (Garden)</a> - learn how to enable and configure the auditing extension for garden clusters</li></ul><h2 id="local-setup-and-development" tabindex="-1">Local Setup and Development <a class="header-anchor" href="#local-setup-and-development" aria-label="Permalink to &quot;Local Setup and Development&quot;">​</a></h2><ul><li><a href="/pr-preview/pr-838/docs/extensions/others/gardener-extension-auditing/getting-started-locally/">Deploying Auditing Extension Locally</a> - learn how to set up a local development environment</li></ul><h2 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h2><p>Please see <a href="https://github.com/gardener/gardener-extension-auditing/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a> for guidelines on how to contribute to this project.</p>',22)]))}const p=t(o,[["render",i]]);export{g as __pageData,p as default};
